<script setup lang="ts">
import {onMounted,reactive,ref,watch,computed} from 'vue'
import {RouterLink,useRoute,useRouter} from 'vue-router'
import {api,readableApiError} from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
import ListPager from '../../components/ListPager.vue'
import {statusLabel} from '../../utils/statusLabels'
type Option={id:number;name:string}
type Item={id:string;title:string;description:string;kind:string;category_name:string;location_name:string;business_status:string;occurred_at:string}
const route=useRoute(),router=useRouter()
const form=reactive({q:'',kind:'',category:'',location:''})
const categories=ref<Option[]>([]),locations=ref<Option[]>([]),items=ref<Item[]>([])
const loading=ref(false),searched=ref(false),error=ref(''),total=ref(0),pageSize=ref(20)
const page=computed(()=>Math.max(1,Number(route.query.page)||1))
let version=0
async function load(){const ticket=++version;loading.value=true;error.value='';for(const key of Object.keys(form) as (keyof typeof form)[])form[key]=typeof route.query[key]==='string'?String(route.query[key]):''
try{const params=new URLSearchParams();for(const [key,value] of Object.entries(form)){const text=String(value??'').trim();if(text)params.set(key,text)}params.set('page',String(page.value));const result=await api<{data:{items:Item[];total:number;page_size:number}}>('/items/?'+params);if(ticket!==version)return;items.value=result.data.items;total.value=result.data.total;pageSize.value=result.data.page_size;searched.value=true}catch(reason){if(ticket===version)error.value=readableApiError(reason,'搜索失败，请重试。')}finally{if(ticket===version)loading.value=false}}
async function search(target=1){const query:Record<string,string>={};for(const [key,value] of Object.entries(form)){const text=String(value??'').trim();if(text)query[key]=text}query.page=String(target);if(route.fullPath===router.resolve({path:'/search',query}).fullPath)await load();else await router.push({path:'/search',query})}
async function reset(){Object.assign(form,{q:'',kind:'',category:'',location:''});await search()}
onMounted(async()=>{try{const result=await api<{data:{categories:Option[];locations:(Option&{parent_id:number|null})[]}}>('/items/metadata/');categories.value=result.data.categories;locations.value=result.data.locations.filter(row=>row.parent_id!==null)}catch(reason){error.value=readableApiError(reason,'筛选项暂时无法加载')}})
watch(()=>route.fullPath,load,{immediate:true})
</script>

<template><div class="page search-page"><header><h1 class="page-title">全局搜索</h1><p class="page-lead">按关键词、类型、类别和校园区域查找公开线索。</p></header><form class="panel search-form" @submit.prevent="search()"><label class="wide"><span>关键词</span><div class="query"><AppIcon name="search"/><input v-model="form.q" placeholder="例如：黑色耳机 图书馆"/></div></label><label><span>线索类型</span><select v-model="form.kind"><option value="">全部</option><option value="LOST">遗失</option><option value="FOUND">招领</option></select></label><label><span>物品类别</span><select v-model="form.category"><option value="">全部</option><option v-for="entry in categories" :key="entry.id" :value="String(entry.id)">{{entry.name}}</option></select></label><label><span>校园区域</span><select v-model="form.location"><option value="">全部</option><option v-for="entry in locations" :key="entry.id" :value="String(entry.id)">{{entry.name}}</option></select></label><footer><button class="button button-ghost" type="button" @click="reset">重置</button><button class="button button-brand" :disabled="loading"><AppIcon name="search"/>{{loading?'搜索中…':'搜索公开线索'}}</button></footer></form><p v-if="error" class="notice error">{{error}}</p><section v-if="searched" class="results"><div class="result-head"><h2>搜索结果</h2><span>共 {{total}} 条</span></div><div v-if="items.length" class="result-list"><RouterLink v-for="item in items" :key="item.id" :to="`/items/${item.id}`" class="result panel"><span class="kind">{{item.kind==='LOST'?'遗失':'招领'}}</span><div><h3>{{item.title}}</h3><p>{{item.description}}</p><small>{{item.category_name}} · {{item.location_name}} · {{new Date(item.occurred_at).toLocaleDateString('zh-CN')}}</small></div><span class="status-tag">{{statusLabel(item.business_status)}}</span><AppIcon name="arrow"/></RouterLink></div><div v-else class="empty">没有符合条件的可见线索。</div><ListPager :page="page" :total="total" :page-size="pageSize" :busy="loading" @change="search"/></section></div></template>

<style scoped>.search-page{max-width:1050px}.search-form{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:34px;padding:26px}.wide{grid-column:1/-1}.search-form label>span{display:block;margin-bottom:8px;color:var(--ct-text-muted);font-size:12px}.query{display:flex;align-items:center;gap:10px;padding:0 13px;border:1px solid var(--ct-border);border-radius:11px;background:var(--ct-bg-soft)}input,select{width:100%;padding:12px;color:var(--ct-text);border:1px solid var(--ct-border);border-radius:11px;background:var(--ct-bg-soft)}.query input{border:0;background:transparent;outline:0}.search-form footer{grid-column:1/-1;display:flex;justify-content:flex-end;gap:10px}.notice{padding:13px;border-radius:10px}.error{color:var(--ct-danger);background:rgba(173,52,52,.08)}.results{margin-top:34px}.result-head{display:flex;justify-content:space-between;align-items:center}.result-head span{color:var(--ct-text-muted)}.result-list{display:grid;gap:10px}.result{display:grid;grid-template-columns:auto 1fr auto auto;gap:16px;align-items:center;padding:18px;box-shadow:none}.kind{color:var(--ct-brand);font-size:12px}.result h3,.result p{margin:0}.result p,.result small{display:block;margin-top:6px;color:var(--ct-text-muted)}.empty{padding:55px;border:1px dashed var(--ct-border);border-radius:16px;text-align:center;color:var(--ct-text-muted)}@media(max-width:700px){.search-form{grid-template-columns:1fr}.wide,.search-form footer{grid-column:auto}.result{grid-template-columns:auto 1fr}.result>.status-tag,.result>svg{display:none}}</style>
